const socket=io({autoConnect:true,reconnection:true});
const unoSocket=io('/uno',{autoConnect:true,reconnection:true});
const app=document.querySelector('#app');
const ROLE={wolf:['🐺','Ma Sói','Mỗi đêm cùng phe Sói chọn một người để loại.'],villager:['🏡','Dân làng','Quan sát, thảo luận và tìm ra Ma Sói.'],seer:['🔮','Tiên tri','Mỗi đêm soi một người để biết họ có phải Ma Sói không.'],witch:['🧪','Phù thủy','Có một lần cứu và một lần dùng độc trong cả ván.'],guard:['🛡️','Bảo vệ','Mỗi đêm bảo vệ một người, không bảo vệ cùng một người hai đêm liên tiếp.'],hunter:['🏹','Thợ săn','Mỗi đêm chọn trước mục tiêu cho phát súng cuối. Nếu bị Phù thủy dùng độc trực tiếp hoặc bị làng bỏ phiếu loại, bạn mất quyền nổ súng.'],cupid:['💘','Cupid','Đêm đầu ghép đôi hai người. Khi một người bị loại, người còn lại cũng rời ván.'],fool:['🤡','Thằng ngố','Phe thứ ba. Bạn thắng ngay nếu chính bạn bị dân làng treo cổ. Bị giết ban đêm không tính thắng.'],hypnotist:['🌀','Thôi miên','Phe thứ tư. Mỗi đêm thôi miên một người, có thể chọn chính mình. Trong phòng 11–12 người, mỗi lượt được chọn hai người khác nhau. Trạng thái thôi miên được duy trì khi Thôi miên còn sống; nếu Thôi miên bị loại, tất cả hiệu ứng thôi miên biến mất. Thắng khi tất cả người còn sống, trừ chính Thôi miên, đều bị thôi miên.']};
const PHASE={lobby:'Phòng chờ',reveal:'Nhận vai trò',night:'Đêm',discussion:'Thảo luận',vote:'Đề cử',lynch:'Xét xử',hunter:'Thợ săn',ended:'Kết thúc'};
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={screen:'home',name:localStorage.getItem('wolf_name')||'',room:null,selection:[],witchChoice:'skip',demoPhase:0,loveOpen:false,loveUnread:0,eliminationNotice:null,willDialog:null,guideIndex:0,lobbyTab:'players',roomsPage:0};
let unoState={room:null,rooms:[],pendingWild:null,joinCode:'',loading:false};
let pending=false;
/* Game audio is synthesized locally with Web Audio; no external assets or API required. */
const soundPrefs={enabled:localStorage.getItem('wolf_sound_enabled')!=='0',volume:Math.max(0,Math.min(1,Number(localStorage.getItem('wolf_sound_volume')??0.55)))};
let soundCtx=null,soundMaster=null,ambientNodes=[];
function audioReady(){if(!soundCtx){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return false;soundCtx=new AC();soundMaster=soundCtx.createGain();soundMaster.gain.value=soundPrefs.enabled?soundPrefs.volume:0;soundMaster.connect(soundCtx.destination)}if(soundCtx.state==='suspended')soundCtx.resume().catch(()=>{});return true}
function soundTone(freq,start,duration,wave='sine',peak=.16,endFreq=null){if(!soundPrefs.enabled||!audioReady())return;const o=soundCtx.createOscillator(),g=soundCtx.createGain(),t=soundCtx.currentTime+start;o.type=wave;o.frequency.setValueAtTime(freq,t);if(endFreq)o.frequency.exponentialRampToValueAtTime(Math.max(1,endFreq),t+duration);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(Math.max(.0002,peak),t+.025);g.gain.exponentialRampToValueAtTime(.0001,t+duration);o.connect(g);g.connect(soundMaster);o.start(t);o.stop(t+duration+.03)}
function soundNoise(start,duration,peak=.035,filter=500){if(!soundPrefs.enabled||!audioReady())return;const n=Math.floor(soundCtx.sampleRate*duration),buf=soundCtx.createBuffer(1,n,soundCtx.sampleRate),d=buf.getChannelData(0);for(let i=0;i<n;i++)d[i]=Math.random()*2-1;const src=soundCtx.createBufferSource(),f=soundCtx.createBiquadFilter(),g=soundCtx.createGain(),t=soundCtx.currentTime+start;src.buffer=buf;f.type='lowpass';f.frequency.value=filter;g.gain.setValueAtTime(.0001,t);g.gain.linearRampToValueAtTime(peak,t+.3);g.gain.exponentialRampToValueAtTime(.0001,t+duration);src.connect(f);f.connect(g);g.connect(soundMaster);src.start(t);src.stop(t+duration+.02)}
function stopAmbient(){for(const n of ambientNodes){try{n.stop()}catch{}}ambientNodes=[]}
function ambientTone(freq,wave,gain,detune=0){if(!soundPrefs.enabled||!audioReady())return;const o=soundCtx.createOscillator(),g=soundCtx.createGain();o.type=wave;o.frequency.value=freq;o.detune.value=detune;g.gain.value=gain;o.connect(g);g.connect(soundMaster);o.start();ambientNodes.push(o)}
function soundNight(){stopAmbient();soundTone(880,0,.55,'sine',.17,440);soundTone(660,.18,.75,'sine',.13,330);soundNoise(.5,4,.025,420);ambientTone(62,'sine',.018);soundTone(240,1.1,1.8,'sine',.035,470);soundTone(470,1.4,2.2,'sine',.025,190)}
function soundDiscussion(){stopAmbient();ambientTone(73,'triangle',.025);ambientTone(110,'sine',.018,5);soundTone(165,0,1.1,'sine',.025,147);soundTone(196,1.4,1.3,'sine',.022,174)}
function soundVote(){stopAmbient();soundTone(740,0,.28,'sine',.18,520);soundTone(520,.22,.48,'sine',.15,740);soundTone(880,.52,.65,'triangle',.08,660)}
function soundElimination(){soundTone(220,0,.65,'triangle',.19,110);soundTone(165,.15,.9,'sawtooth',.07,55);soundNoise(.05,.65,.045,700)}
function soundVictory(){stopAmbient();[523,659,784,1047].forEach((n,i)=>soundTone(n,i*.19,.75,'triangle',.11,n*1.01));soundTone(392,.55,1.15,'sine',.07,784)}
function soundPhaseChange(previous,next,r){if(!soundPrefs.enabled)return;if(next==='night'&&previous!=='night')soundNight();else if(next==='discussion'&&previous!=='discussion')soundDiscussion();else if(next==='vote'&&previous!=='vote')soundVote();if(next==='ended'&&previous!=='ended')soundVictory()}
function soundPanel(){return '<aside class="sound-panel" aria-label="Điều khiển âm thanh"><button type="button" data-sound-toggle class="sound-toggle" aria-pressed="'+soundPrefs.enabled+'">'+(soundPrefs.enabled?'🔊 Âm thanh: Bật':'🔇 Âm thanh: Tắt')+'</button><label>Âm lượng <input data-sound-volume type="range" min="0" max="1" step="0.05" value="'+soundPrefs.volume+'"></label></aside>'}
function setSoundEnabled(on){soundPrefs.enabled=on;localStorage.setItem('wolf_sound_enabled',on?'1':'0');if(on){audioReady();if(soundMaster)soundMaster.gain.setTargetAtTime(soundPrefs.volume,soundCtx.currentTime,.04);const p=state.room?.phase;if(p==='night')soundNight();else if(p==='discussion')soundDiscussion()}else{if(soundMaster&&soundCtx)soundMaster.gain.setTargetAtTime(0,soundCtx.currentTime,.04);stopAmbient()}render()}

function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),3500)}
function rpc(event,data){return new Promise(resolve=>{socket.timeout(8000).emit(event,data,(err,result)=>resolve(err?{ok:false,error:'Máy chủ không phản hồi. Kiểm tra kết nối.'}:result||{ok:false,error:'Lỗi không xác định.'}))})}
function saveSession(code,playerId){localStorage.setItem('wolf_session',JSON.stringify({code,playerId}));}
function clearSession(){localStorage.removeItem('wolf_session');state.room=null;state.screen='home';state.loveOpen=false;state.loveUnread=0;state.eliminationNotice=null;render()}
function go(screen){state.screen=screen;state.selection=[];render()}
function header(title='MA SÓI HUYỀN BÍ',back=false){return `<header class="top"><div class="row">${back?'<button class="iconbtn" data-go="home" aria-label="Trở lại">←</button>':''}<div><h1>${title}</h1><small>🌙 Ngôi làng bí ẩn</small></div></div><span class="badge">${socket.connected?'● Trực tuyến':'○ Mất mạng'}</span></header>`}
function dock(){return `<nav class="dock"><button data-go="home"><b>⌂</b>Trang chủ</button><button data-go="rooms"><b>♜</b>Phòng chơi</button><button data-go="guide"><b>📖</b>Hướng dẫn</button></nav>`}
function home(){return `<div class="home-page">${header()}<section class="home-hero"><div class="home-stars" aria-hidden="true">✦ · ✧ · ✦</div><div class="home-moon" aria-hidden="true">🌕</div><div class="home-wolf" aria-hidden="true">🐺</div><div class="home-eyebrow">TRÒ CHƠI SUY LUẬN TRỰC TUYẾN</div><h2>MA SÓI <span>HUYỀN BÍ</span></h2><p>Bạn sẽ tin ai khi màn đêm buông xuống?</p><div class="home-silhouette" aria-hidden="true">♜ ♟ ♜ ♟ ♜</div></section><section class="home-menu"><button class="home-primary" data-go="rooms"><span>🐺</span><span><strong>CHƠI NGAY</strong><small>Khám phá các phòng đang chờ</small></span><span class="home-arrow">→</span></button><div class="home-shortcuts"><button data-go="create"><span class="home-shortcut-icon">✦</span><strong>Tạo phòng</strong><small>Mời bạn bè cùng chơi</small></button><button data-go="join"><span class="home-shortcut-icon">⌁</span><strong>Vào phòng</strong><small>Tham gia bằng mã</small></button></div><button class="home-ai-button" data-go="ai"><span class="home-ai-icon">🤖</span><span><strong>CHƠI VỚI MÁY</strong><small>Bạn và 11 đối thủ AI · Ván 12 người · Không cần chờ người chơi</small></span><span class="home-ai-arrow">→</span></button></section><section class="home-hub-entry"><div class="home-hub-copy"><span class="home-hub-kicker">GAME HUB</span><strong>Thêm niềm vui cùng bạn bè</strong><small>Khám phá những trò chơi nhiều người trong Ma Sói Huyền Bí.</small></div><button type="button" class="home-uno-button" data-go="unoHub"><span class="home-uno-mark">UNO</span><span><strong>UNO PARTY</strong><small>Đánh bài trực tuyến · 2–10 người</small></span><span class="home-uno-arrow">→</span></button></section><section class="home-info"><div class="home-info-heading"><span>🌙</span><div><h3>Đêm xuống, bí mật bắt đầu</h3><p>Tham gia ngôi làng, khám phá vai trò và tìm ra phe chiến thắng.</p></div></div><div class="home-features"><span>👥 5–12 người</span><span>🎭 9 vai trò</span><span>✨ Quản trò tự động</span></div></section><footer class="home-author">Phát triển bởi <strong>Dương Thanh Sang</strong></footer></div>${dock()}`}

function nameField(){return `<div class="field"><label for="playerName">Biệt danh của bạn</label><input id="playerName" maxlength="18" autocomplete="nickname" value="${escapeHTML(state.name)}" placeholder="Nhập tên của bạn"></div>`}
function create(){return `${header('Tạo phòng',true)}<section class="panel"><h3>✦ Lập ngôi làng mới</h3>${nameField()}<div class="field"><label for="roomName">Tên phòng</label><input id="roomName" maxlength="24" value="Hội Bạn Thân"></div><div class="field"><label>Số người tối đa</label><input value="12 người" disabled></div><div class="field"><label for="discussion">Thời gian thảo luận</label><select id="discussion"><option value="60">60 giây</option><option value="100" selected>100 giây</option><option value="150">150 giây</option><option value="240">240 giây</option></select></div><label class="row"><input id="private" type="checkbox" style="width:20px;min-height:20px"> Phòng riêng (chỉ vào bằng mã)</label><p class="hint">Mặc định là phòng công khai, mọi người có thể tìm thấy trong danh sách.</p><hr class="divider"><p class="muted">Vai trò: Ma Sói, Dân làng, Tiên tri, Phù thủy, Bảo vệ, Thợ săn, Cupid, Thằng ngố và Thôi miên. Tự động chia vai theo số người.</p><button class="btn gold full" data-action="create">Tạo phòng</button></section>${dock()}`}
function ai(){return `${header('Chơi với máy',true)}<section class="panel"><h3>🤖 Đối đầu với 11 người chơi máy</h3><p class="muted">Bạn sẽ tham gia một ván 12 người (1 bạn và 11 đối thủ máy) với đầy đủ vai trò. Các đối thủ máy tự hành động ban đêm, thảo luận và bỏ phiếu vào ban ngày.</p>${nameField()}<div class="hint">Thời gian thảo luận: 45 giây · Bỏ phiếu: 30 giây</div><button class="btn gold full" data-action="create-ai" style="margin-top:14px">🎮 Bắt đầu chơi</button></section>${dock()}`}
function join(){return `${header('Vào phòng',true)}<section class="panel"><h3>🔑 Nhập mã phòng</h3>${nameField()}<div class="field"><label for="roomCode">Mã phòng 6 ký tự</label><input id="roomCode" maxlength="6" autocapitalize="characters" placeholder="VD: A1B2C3" value="${escapeHTML(state.joinCode||'')}"></div><button class="btn gold full" data-action="join">Vào ngôi làng</button></section>${dock()}`}
function rooms(){return `${header('Danh sách phòng',true)}${nameField()}<div class="row between"><h2>Phòng công khai</h2><button class="btn small ghost" data-action="refresh">↻ Làm mới</button></div><div id="roomlist" class="panel"><div class="empty">Đang tải danh sách phòng...</div></div><button class="btn full" data-go="create">＋ Tạo phòng mới</button>${dock()}`}
function guide(){const entries=Object.entries(ROLE),i=Math.max(0,Math.min(state.guideIndex,entries.length)),isIntro=i===0,role=entries[i-1];return `${header('Hướng dẫn',true)}<section class="panel guide-card">${isIntro?'<h3>📖 Luật chơi cơ bản</h3><p>Ban đêm, các vai trò sử dụng kỹ năng. Ban ngày, người chơi thảo luận và bỏ phiếu tìm Sói.</p><p>Phe Làng thắng khi loại hết Sói; phe Sói thắng khi số Sói ít nhất bằng số người còn lại. Một số vai trò có điều kiện thắng riêng.</p>':`<div class="guide-symbol">${role[1][0]}</div><h3>${role[1][1]}</h3><p>${role[1][2]}</p>`}</section><div class="page-controls"><button class="btn small ghost" data-guide-page="-1" ${i===0?'disabled':''}>← Trước</button><span>${i+1}/${entries.length+1}</span><button class="btn small gold" data-guide-page="1" ${i===entries.length?'disabled':''}>Tiếp →</button></div>${dock()}`}

const AVATAR_OPTIONS=[['explorer','Nhà thám hiểm','🧭'],['scholar','Học giả','🎓'],['knight','Hiệp sĩ','⚔️'],['queen','Nữ hoàng','👑'],['king','Nhà vua','♔']];
function pairsForAvatar(id){return ({explorer:'nhanvat (6) (1).png',scholar:'nhanvat (5) (1).png',knight:'nhanvat (4) (1).png',queen:'nhanvat (3) (1).png',king:'nhanvat (2) (1).png'})[id]||'nhanvat (6) (1).png'}
function avatarImage(p){const entry=AVATAR_OPTIONS.find(x=>x[0]===p.avatar)||AVATAR_OPTIONS[0];return '<img class="character-portrait" src="/'+encodeURIComponent(pairsForAvatar(entry[0]))+'" alt="'+entry[1]+'" onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'inline\'"><span class="character-fallback" style="display:none">'+entry[2]+'</span>'}
function avatarPicker(r){const current=r.players.find(p=>p.id===r.self.id)?.avatar||'explorer';return '<div class="avatar-picker"><strong>🎭 Chọn nhân vật của bạn</strong><div class="avatar-options">'+AVATAR_OPTIONS.map(x=>'<button type="button" class="avatar-option '+(current===x[0]?'active':'')+'" data-avatar="'+x[0]+'" title="'+x[1]+'"><img src="/'+encodeURIComponent(pairsForAvatar(x[0]))+'" alt="'+x[1]+'" onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'inline\'"><span class="character-fallback" style="display:none">'+x[2]+'</span><small>'+x[1]+'</small></button>').join('')+'</div></div>'}
function playerCard(p,selfId,selected=false,index=null,votable=false,actionable=false,voteNumbers=[],lynchChoice=null,accused=false,wolfPickers=[]){const room=state.room;const heart=room?.self?.lover&&(p.id===room.self.id||p.id===room.self.lover)?((p.id===room.self.id?room.self.role:room.self.loverRole)==='wolf'?'🖤':'❤️'):'';const wolfMate=room?.self?.role==='wolf'&&room.self.wolfTeam?.some(x=>x.id===p.id&&p.id!==selfId);const number=index===null?'':`<span class="player-number">${index+1}</span>`;const canSeeWill=p.id===selfId||!p.alive;const deathMark=!p.alive?(p.deathStyle==='noose'?'<span class="death-mark death-noose"><img class="noose-art" src="/assets/khan-treo.webp?v=2" alt="Khăn treo cổ"></span>':p.deathStyle==='claw'?`<span class="death-mark death-claw"><svg class="claw-art" viewBox="0 0 559 393" role="img" aria-label="Dấu móng vuốt sói"><path d="M 558,44 L555,43 L505,61 L482,72 L457,87 L433,104 L409,115 L413,117 L398,129 L384,134 L382,136 L382,139 L363,156 L331,194 L304,220 L286,233 L277,245 L271,248 L266,260 L246,284 L230,298 L224,306 L218,308 L213,316 L205,319 L196,320 L190,325 L189,329 L186,332 L186,336 L183,342 L176,348 L172,354 L164,358 L169,362 L146,386 L145,391 L148,391 L157,386 L176,372 L212,342 L250,306 L259,299 L264,297 L272,289 L279,286 L279,282 L282,278 L295,271 L316,250 L322,247 L333,238 L334,229 L344,221 L354,208 L367,203 L379,196 L387,188 L389,184 L389,177 L395,171 L392,170 L382,177 L379,175 L386,171 L388,167 L406,161 L408,159 L409,153 L414,149 L416,142 L420,138 L422,138 L423,135 L428,132 L428,130 L444,117 L461,100 L480,88 L506,76 L510,73 L508,71 L523,61 L543,51 L555,47 Z M 428,1 L424,1 L399,9 L321,47 L279,70 L268,79 L262,81 L261,84 L249,94 L236,99 L238,102 L230,109 L224,111 L161,179 L152,185 L145,194 L137,196 L135,198 L134,204 L130,209 L125,208 L122,211 L120,220 L117,225 L102,240 L100,245 L88,255 L81,265 L75,267 L64,277 L54,278 L44,285 L44,287 L46,288 L40,301 L35,302 L33,304 L33,308 L30,314 L20,325 L16,326 L14,335 L5,341 L1,345 L1,347 L4,347 L20,338 L58,310 L72,298 L104,266 L136,242 L142,234 L149,230 L161,218 L177,206 L184,198 L181,193 L188,184 L197,175 L208,173 L212,169 L224,162 L233,153 L235,149 L235,144 L242,138 L239,137 L229,143 L226,143 L225,140 L237,132 L248,128 L252,128 L253,117 L266,106 L266,103 L286,87 L289,88 L293,86 L318,63 L343,50 L359,37 L418,8 L422,9 Z M 456,49 L442,51 L412,61 L371,80 L342,99 L333,100 L318,115 L302,122 L287,135 L277,140 L271,148 L265,150 L265,153 L271,153 L266,157 L266,161 L262,166 L254,167 L246,171 L229,186 L227,194 L228,197 L230,198 L235,194 L237,194 L239,197 L233,200 L235,202 L233,205 L227,207 L229,213 L221,224 L215,227 L218,231 L217,233 L190,255 L189,253 L194,245 L192,244 L180,256 L166,267 L168,273 L162,278 L155,289 L137,305 L132,313 L124,321 L128,322 L154,306 L170,289 L186,278 L201,262 L226,245 L235,235 L241,233 L243,231 L243,227 L259,213 L269,207 L274,200 L299,178 L305,171 L306,165 L310,161 L312,156 L324,152 L325,147 L333,143 L333,138 L339,128 L343,124 L347,123 L355,113 L384,97 L388,97 L391,99 L401,97 L401,93 L410,83 L415,81 L420,74 L429,71 L432,67 L439,67 L440,61 Z"/></svg></span>`:''):'';const inner=`${number}${canSeeWill?`<span class="will-book-btn ${p.will?'has-will':''}" data-will-player="${p.id}" role="button" tabindex="0" title="${p.id===selfId?'Di chúc của bạn':'Xem di chúc'}" aria-label="${p.id===selfId?'Mở di chúc của bạn':'Xem di chúc của '+escapeHTML(p.name)}">📓</span>`:''}${deathMark}${wolfPickers.length?`<span class="wolf-pick-badges" title="${escapeHTML(wolfPickers.map(x=>x.voterName).join(', '))}">${wolfPickers.map(x=>`<span class="wolf-pick-mark">🐺 #${x.voterNumber}</span>`).join('')}</span>`:''}${wolfMate?'<span class="wolf-mate-mark" title="Đồng đội Ma Sói">🐺 Đồng đội</span>':""}${heart?`<span class="lover-heart" title="Ghép đôi">${heart}</span>`:""}${voteNumbers.length?`<span class="vote-numbers">🗳️ ${voteNumbers.join(', ')}</span>`:''}${lynchChoice?`<span class="lynch-mark">${lynchChoice==='kill'?'👍':'👎'}</span>`:''}${accused?'<span class="accused-mark">⚖️ XÉT XỬ</span>':''}${p.hypnotized?'<span class="hypnotized-mark" title="Đã bị thôi miên">🌀 Bị thôi miên</span>':''}<div class="avatar ${!p.alive?'dead':''}">${avatarImage(p)}</div><strong class="player-visible-name" title="${escapeHTML(p.name)}">${escapeHTML(p.name)}</strong><small>${!p.alive?(p.deathStyle==='noose'?'Bị treo cổ':p.deathStyle==='left'?'Đã rời trận':'Bị giết')+(p.isBot&&p.deathStyle!=='noose'?' · 🤖 Máy':''):p.isBot?'🤖 Máy':p.online===false?'Mất kết nối':p.id===selfId?'Bạn':'Còn sống'}</small>${votable?`<span class="vote-prompt">${selected?'✓ Phiếu hiện tại':'🗳️ Bỏ phiếu'}</span>`:actionable?`<span class="vote-prompt">${selected?'✓ Đã chọn':'✦ Chọn'}</span>`:''}`;const cls=`player ${!p.alive?'eliminated':''} ${wolfMate?'wolf-teammate':''} ${p.hypnotized?'is-hypnotized':''} ${p.id===selfId?'me':''} ${!p.alive?'dead':''} ${selected?'selected':''} ${votable||actionable?'vote-target':''}`;return votable||actionable?`<button type="button" class="${cls}" ${votable?`data-vote-player="${p.id}"`:`data-role-player="${p.id}"`} aria-label="${votable?'Bỏ phiếu cho':'Chọn'} người chơi số ${index+1}: ${escapeHTML(p.name)}">${inner}</button>`:`<div class="${cls}">${inner}</div>`}

function roleSummary(r){const counts=r.roleCounts||{};return `<section class="panel"><div class="heading"><h3>🎭 Thành phần vai trò</h3><span class="badge">${r.players.length} người</span></div><p class="muted">Số lượng vai trò dự kiến khi bắt đầu với ${r.players.length} người. Vai trò từng người vẫn được giữ bí mật.</p><div class="role-count-grid">${Object.entries(ROLE).filter(([key])=>counts[key]>0).map(([key,info])=>`<div class="role-count"><span>${info[0]}</span><span>${info[1]}</span><strong>×${counts[key]}</strong></div>`).join('')}</div><p class="hint">Nếu có người vào hoặc rời phòng, bảng sẽ tự cập nhật trước khi bắt đầu.</p></section>`}
function lobby(r){let isHost=r.host===r.self.id;return `${header('Phòng chờ',false)}<div class="phase lobby-room-info"><span class="badge">Phòng: ${r.code}</span><span class="lobby-room-count">${r.players.length}/${r.settings.max} người</span><button class="btn small ghost" data-action="copy">⧉ Sao chép</button></div><div class="lobby-tabs"><button data-lobby-tab="players" class="${state.lobbyTab==='players'?'active':''}">👥 Người chơi</button><button data-lobby-tab="roles" class="${state.lobbyTab==='roles'?'active':''}">🎭 Vai trò</button><button data-lobby-tab="chat" class="${state.lobbyTab==='chat'?'active':''}">💬 Chat</button></div><div class="lobby-content">${state.lobbyTab==='players'?`<section class="panel"><div class="heading"><h3>Người tham gia</h3><span class="badge">${r.players.filter(p=>p.ready).length} sẵn sàng</span></div><div class="gridplayers lobby-large-grid">${r.players.map((p,i)=>`<div class="player ${p.id===r.self.id?'me':''}"><span class="player-number">${i+1}</span><div class="avatar">${avatarImage(p)}</div><strong>${escapeHTML(p.name)}</strong><small>${p.id===r.host?'Chủ phòng':p.isBot?'🤖 Máy · Sẵn sàng':p.ready?'✓ Sẵn sàng':p.online?'Đang chờ':'Ngoại tuyến'}</small>${isHost&&p.id!==r.host?`<button class="kickbtn" data-kick="${p.id}" aria-label="Mời ${escapeHTML(p.name)} ra khỏi phòng">✕ Mời ra</button>`:''}</div>`).join('')}</div></section>`:state.lobbyTab==='roles'?roleSummary(r):chat(r)}</div>${avatarPicker(r)}<div class="stack lobby-buttons">${isHost&&!r.botMode?`<button class="btn ghost full" data-action="add-bot" ${r.players.length>=r.settings.max?'disabled':''}>🤖 Thêm bot (+1 người)</button>`:''}${isHost?'<button class="btn gold full" data-action="start">Bắt đầu ván (tối thiểu 5 người)</button>':`<button class="btn gold full" data-action="ready">${r.players.find(p=>p.id===r.self.id)?.ready?'✓ Đã sẵn sàng – nhấn để hủy':'Tôi đã sẵn sàng'}</button>`}<button class="btn ghost full" data-action="leave">Rời phòng</button></div>`}
function chat(r){let allowed=['lobby','discussion'].includes(r.phase)&&r.self.alive;return `<section class="panel"><h3>💬 Trò chuyện</h3><div class="chat" id="chatlog">${r.messages.map(m=>m.type==='system'?`<div class="message system">✧ ${escapeHTML(m.message)}</div>`:`<div class="message"><strong>${escapeHTML(m.name)}:</strong> ${escapeHTML(m.message)}</div>`).join('')||'<div class="empty">Chưa có tin nhắn</div>'}</div>${allowed?'<form class="composer" id="chatForm"><input id="chatInput" maxlength="350" placeholder="Nhập tin nhắn..." autocomplete="off" aria-label="Nhập tin nhắn"><button class="btn small" type="submit">Gửi</button></form>':'<p class="hint">Chat chỉ mở ở phòng chờ và lúc thảo luận, dành cho người còn sống.</p>'}</section>`}
function roleCard(r){let role=ROLE[r.self.role]||ROLE.villager;const mates=r.self.role==='wolf'?(r.self.wolfTeam||[]).filter(p=>p.id!==r.self.id):[];return `<section class="cardrole"><div class="symbol">${role[0]}</div><p class="pill">VAI TRÒ BÍ MẬT CỦA BẠN</p><h2>${role[1]}</h2><p>${role[2]}</p><span class="badge">${r.self.role==='wolf'?'Phe Sói':r.self.role==='fool'?'Phe thứ ba · Thằng ngố':r.self.role==='hypnotist'?'Phe thứ tư · Thôi miên':'Phe Làng / vai đặc biệt'}</span>${r.self.role==='wolf'?`<p class="wolf-team-info">🐺 Đồng đội: ${mates.length?mates.map(p=>escapeHTML(p.name)).join(', '):'Bạn là Ma Sói duy nhất'}</p>`:''}${r.self.lover?`<p class="role-lover-note">💞 Bạn ${r.self.role==='wolf'?'🖤':'❤️'} · ${escapeHTML(r.players.find(p=>p.id===r.self.lover)?.name||'Ẩn')} ${r.self.loverRole==='wolf'?'🖤':'❤️'}</p>`:''}</section>`}
function willDialog(r){const d=state.willDialog;if(!d)return '';const target=r.players.find(p=>p.id===d.playerId);if(!target||target.id!==r.self.id&&target.alive)return '';const editable=target.id===r.self.id&&r.self.alive&&r.phase!=='ended';return `<div class='will-modal-overlay' role='presentation'><section class='will-modal' role='dialog' aria-modal='true' aria-labelledby='will-modal-title'><div class='heading'><h3 id='will-modal-title'>📓 Di chúc của ${escapeHTML(target.name)}</h3><button type='button' class='btn small ghost' data-close-will='1' aria-label='Đóng cửa sổ'>✕ Đóng</button></div>${editable?`<form id='playerWillForm'><p class='muted'>Tối đa 100 ký tự. Chỉ bạn có thể chỉnh sửa di chúc của mình.</p><textarea id='playerWillInput' maxlength='100' rows='3' placeholder='Viết lời nhắn cuối cùng...'>${escapeHTML(target.will||'')}</textarea><div class='will-modal-actions'><button type='button' class='btn ghost' data-close-will='1'>Hủy</button><button type='submit' class='btn gold'>💾 Lưu di chúc</button></div></form>`:`<p class='will-modal-text'>${target.will?escapeHTML(target.will):'Người chơi chưa viết di chúc.'}</p><button type='button' class='btn ghost full' data-close-will='1'>Đóng</button>`}</section></div>`}
function loveLetters(r){if(!r.self.lover)return '';const lover=r.players.find(p=>p.id===r.self.lover);const active=!!lover&&r.phase!=='lobby';const letters=r.loveLetters||[];return `<aside class="love-floating"><button type="button" class="love-bubble" data-love-toggle="1" aria-label="Mở hoặc đóng thư tình yêu">💌${state.loveUnread?`<span class="love-unread">${state.loveUnread}</span>`:""}</button>${state.loveOpen?`<section class="panel love-panel"><div class="heading"><h3>💌 Thư Cupid</h3><button class="btn small ghost" data-love-toggle="1">${state.loveOpen?'Thu gọn':'Mở thư'}${state.loveUnread?' ('+state.loveUnread+' mới)':''}</button></div><p class="muted">💞 Ghép đôi với ${escapeHTML(lover?.name||'Người bí mật')} · Chỉ hai người đọc được thư</p>${state.loveOpen?`<div class="love-log" id="loveLog">${letters.length?letters.map(m=>`<div class="love-message ${m.from===r.self.id?'mine':''}"><small>${m.from===r.self.id?'Bạn':escapeHTML(lover?.name||'Người ấy')}</small><div>${escapeHTML(m.message)}</div></div>`).join(''):'<p class="muted">Chưa có thư nào. Hãy gửi lời nhắn đầu tiên!</p>'}</div>${active?'<form id="loveForm" class="composer"><input id="loveInput" maxlength="350" autocomplete="off" placeholder="Viết thư bí mật..." aria-label="Viết thư Cupid"><button class="btn small" type="submit">Gửi 💌</button></form>':'<p class="hint">Hộp thư vẫn mở kể cả khi một trong hai người đã bị loại.</p>'}`:''}</section>`:""}</aside>`}
function actions(r){const a=r.action;if(!a||a.kind==='wait')return '<section class="role-action-panel role-wait"><h3>🌙 Đang gọi các vai trò...</h3><p>Hãy chờ đến lượt bạn.</p></section>';
const kind=a.kind,role=ROLE[kind]||['✨','Hành động',''],draftIds=state.selection.length?state.selection:Array.isArray(a.draft?.targets)?a.draft.targets:[a.draft?.target].filter(Boolean),selected=draftIds.map(id=>r.players.find(p=>p.id===id)).filter(Boolean);
const tips={guard:'Có thể bảo vệ chính mình hoặc người khác khỏi Sói. Không thể bảo vệ cùng một người hai đêm liên tiếp.',witch:'Có thể dùng bình cứu cho người bị Sói nhắm đến, kể cả chính mình; hoặc dùng bình độc hay bỏ qua.',hunter:'Chọn trước một người. Nếu bạn bị Sói loại trong đêm, người này sẽ là mục tiêu.',seer:'Chọn một người để soi chính xác vai trò của họ. Kết quả chỉ hiện cho Tiên tri và vẫn lưu sau khi hết lượt.',wolf:'Chọn một người để phe Sói tấn công.',cupid:'Chọn hai người để ghép đôi.',hypnotist:'Có thể chọn chính mình. Phòng 11–12 người chọn hai người mỗi đêm; phòng ít hơn chọn một người. Chỉ chọn người chưa bị thôi miên.'};
const color={guard:'guard',witch:'witch',hunter:'hunter',seer:'seer',wolf:'wolf',cupid:'cupid',hypnotist:'hypnotist'}[kind]||'guard';
const witch=kind==='witch',mode=a.draft?.choice||state.witchChoice,needsTarget=!witch||mode==='poison';
const chosen=selected.map((p,i)=>'<div class="role-picked"><span class="role-picked-avatar">👤</span><strong>'+escapeHTML(p.name)+'</strong><small>Số '+(r.players.indexOf(p)+1)+'</small><button type="button" data-unselect="'+p.id+'" aria-label="Bỏ chọn">✕</button></div>').join('');
const canConfirm=!a.submitted&&(witch?(mode==='skip'||mode==='heal'&&r.self.witchHeal&&!!a.witchVictim||mode==='poison'&&r.self.witchPoison&&selected.length===1):kind==='cupid'?selected.length===2:kind==='hypnotist'&&r.players.length>=11?selected.length===2:selected.length===1);
return `<section class="role-action-panel role-${color}"><div class="role-action-heading"><span class="role-action-icon">${role[0]}</span><div><strong>${role[1]} ơi, đến lượt bạn!</strong><p>${escapeHTML(tips[kind]||role[2])}</p></div></div>${witch?`<div class="role-potions"><button type="button" data-witch="heal" class="${mode==='heal'?'active':''}" ${!r.self.witchHeal||!a.witchVictim?'disabled':''}>💚 Cứu · ${r.self.witchHeal?'1':'0'}</button><button type="button" data-witch="poison" class="${mode==='poison'?'active':''}" ${!r.self.witchPoison?'disabled':''}>🧪 Bình độc · ${r.self.witchPoison?'1':'0'}</button><button type="button" data-witch="skip" class="${mode==='skip'?'active':''}">⏭️ Bỏ qua</button></div>${a.witchVictim?'<p class="role-witch-info">🐺 Người bị Sói nhắm đến: '+escapeHTML(a.witchVictim)+(a.witchVictim===r.players.find(p=>p.id===r.self.id)?.name?' (chính bạn — có thể tự cứu)':'')+'</p>':''}`:''}<div class="role-action-instruction">${witch&&mode==='heal'?'💚 Bạn chọn cứu người bị Sói nhắm đến.':witch&&mode==='skip'?'⏭️ Bạn chọn bỏ qua lượt này.':kind==='cupid'||kind==='hypnotist'&&r.players.length>=11?'👆 Chạm vào hai người trên bàn chơi để chọn mục tiêu.':'👆 Chạm vào một người trên bàn chơi để chọn mục tiêu.'}</div>${needsTarget?`<div class="role-picked-area">${chosen||'<span class="role-picked-empty">Chưa chọn mục tiêu</span>'}</div>`:''}<button type="button" class="role-confirm" data-confirm-role="1" ${canConfirm?'':'disabled'}>${a.submitted?'✓ Đã xác nhận':'✓ Xác nhận lựa chọn'}</button><p class="role-action-note">${a.submitted?'✓ Đã xác nhận lượt này.':a.draft?'✓ Đã lưu trên máy chủ. Bạn vẫn có thể thay đổi trước khi hết giờ.':'⏳ Hết giờ, lựa chọn đã lưu sẽ tự động xác nhận.'}</p></section>`}

function roleCardTargetable(r,p){const a=r.action;if(!a||a.kind==='wait'||a.kind==='vote'||a.submitted||!r.self.alive)return false;if(a.kind==='witch'&&state.witchChoice!=='poison')return false;return (a.targets||[]).some(t=>t.id===p.id)}
function lynchPanel(r){if(r.phase!=='lynch')return '';const target=r.players.find(p=>p.id===r.lynchTarget);const votes=r.lynchChoices||[];const kills=votes.filter(v=>v.choice==='kill').length,spares=votes.filter(v=>v.choice==='spare').length;const canVote=r.self.alive&&r.self.id!==r.lynchTarget;const status=r.self.id===r.lynchTarget?'⚖️ Bạn đang bị xét xử, không thể bỏ phiếu.':!r.self.alive?'👀 Bạn đang theo dõi kết quả.':r.action?.choice?'✓ Bạn đang chọn '+(r.action.choice==='kill'?'Giết':'Không giết')+'. Có thể đổi khi còn thời gian.':'Hãy chọn Giết hoặc Không giết; bạn có thể đổi lựa chọn trước khi hết giờ.';const killClass='lynch-choice lynch-kill '+(r.action?.choice==='kill'?'active':'');const spareClass='lynch-choice lynch-spare '+(r.action?.choice==='spare'?'active':'');return `<section class='panel lynch-panel lynch-vote-card'><h3>⚖️ Hãy biểu quyết! Giết hay không giết?</h3><div class='lynch-vote-layout'><div class='lynch-vote-side'><div class='lynch-vote-count' aria-label='Số phiếu Giết'>${kills}</div>${canVote?`<button type='button' class='${killClass}' data-lynch='kill'>👎 Giết</button>`:`<span class='lynch-choice lynch-kill readonly'>👎 Giết</span>`}</div><div class='lynch-vote-person'><div class='lynch-vote-avatar'>${target?avatarImage(target):'👤'}</div><div class='lynch-vote-name'>${escapeHTML(target?.name||'Người bị xét xử')}</div></div><div class='lynch-vote-side'><div class='lynch-vote-count' aria-label='Số phiếu Không giết'>${spares}</div>${canVote?`<button type='button' class='${spareClass}' data-lynch='spare'>👍 Không giết</button>`:`<span class='lynch-choice lynch-spare readonly'>👍 Không giết</span>`}</div></div><p class='lynch-vote-footnote'>${canVote?'Chỉ loại khi số phiếu Giết nhiều hơn Không giết.':status}</p></section>`}
function eliminationDialog(){const n=state.eliminationNotice;if(!n)return '';const me=state.room?.players.find(p=>p.id===state.room?.self?.id);const title=me?.deathStyle==='noose'?'Bạn đã bị treo cổ!':me?.deathStyle==='left'?'Bạn đã rời trận!':'Bạn đã bị giết!';return `<div class="elimination-overlay" role="presentation"><section class="elimination-dialog" role="alertdialog" aria-modal="true" aria-labelledby="elimination-title" aria-describedby="elimination-desc"><div class="elimination-symbol">👻</div><h2 id="elimination-title">${title}</h2><p id="elimination-desc">${escapeHTML(n)}</p><p class="muted">Bạn có thể tiếp tục theo dõi diễn biến ván chơi.</p><button class="btn gold full" data-dismiss-elimination="1">Đã hiểu · Tiếp tục theo dõi</button></section></div>`}
function revealScreen(r){const role=ROLE[r.self.role]||ROLE.villager;return `<div class="game-screen reveal-screen">${header('Bí mật của bạn')}<section class="reveal-card"><div class="reveal-emblem">${role[0]}</div><p class="reveal-kicker">🎭 VAI TRÒ CỦA BẠN</p><h2>${role[1]}</h2><p>${role[2]}</p><p class="reveal-secret">🔒 Chỉ bạn nhìn thấy vai trò này</p>${r.players.some(p=>p.isBot)?`<p class="reveal-secret">🤖 Ván này có ${r.players.filter(p=>p.isBot).length} người chơi máy · Tổng ${r.players.length} người</p>`:''}<div class="reveal-count">Đêm đầu tiên bắt đầu sau <strong id="clock">00:10</strong></div></section></div>`}
function game(r){const night=r.phase==='night';let phase=r.phase==='night'?`Đêm ${r.day}`:r.phase==='hunter'?'Lượt Thợ săn':r.phase==='lynch'?'Phiên xét xử':r.phase==='vote'?'Giai đoạn bỏ phiếu':`Ngày ${r.day}`;return `<div class="game-screen village-screen village-weather ${['night','lynch','vote','hunter'].includes(r.phase)?'village-decision':'village-discussion'} ${r.action?.kind&&r.action.kind!=='wait'&&night?'village-acting':''} ${night?'village-night':'village-day'}"><div class="village-sky" aria-hidden="true">${night?'🌙 ✦ ✧ ✦':'☀️ ☁️ ☁️'}</div><div class="village-brand">🐺 MA SÓI HUYỀN BÍ <span>· ${escapeHTML(r.name)}</span></div><section class="phase village-phase ${r.action?.kind&&r.action.kind!=='wait'&&r.phase==='night'?'phase-your-turn':''}"><span class="badge">${night?'🌙':'☀️'} ${phase}</span><div class="clock" id="clock">--:--</div><small>${r.players.filter(p=>p.alive).length} còn sống</small></section>${r.phase==='night'&&r.self.alive?`<div class="turn-banner ${r.action?.kind&&r.action.kind!=='wait'?'turn-active':'turn-wait'}">${r.action?.kind&&r.action.kind!=='wait'?`<div class="turn-emblem">${ROLE[r.self.role]?.[0]||'✨'}</div><div><strong>ĐẾN LƯỢT BẠN — ${ROLE[r.self.role]?.[1]||'Vai trò'}</strong><small>${ROLE[r.self.role]?.[2]||'Hãy chọn mục tiêu trên khung nhân vật.'} · 15 giây</small></div>`:`<span>🌙 Đang gọi các vai trò trong đêm. Hãy chờ đến lượt bạn.</span>`}</div>`:''}${!r.self.alive?'<div class="panel"><p>👻 Bạn đã bị loại. Bạn có thể theo dõi ván nhưng không thể chat hoặc bỏ phiếu.</p></div>':''}<section class="panel village-board"><div class="heading"><h3>🏘️ Ngôi làng</h3><span class="pill">${r.players.length} người</span>${r.players.some(p=>p.isBot)?`<span class="pill">🤖 ${r.players.filter(p=>p.isBot).length} máy</span>`:''}</div>${r.phase==='night'&&r.action?.kind!=='wait'&&!r.action?.submitted?'<p class="hint">✨ Chạm vào khung nhân vật để chọn mục tiêu; lựa chọn tự lưu.</p>':''}${r.phase==='vote'?'<div class="village-vote-announcement" role="status">🗳️ Giai đoạn bỏ phiếu: Hãy chọn người chơi mà bạn nghi ngờ</div>':''}${r.phase==='lynch'?'<p class="hint">⚖️ Số thứ tự người bỏ phiếu đề cử và lựa chọn 👍/👎 được hiển thị công khai.</p>':''}${r.phase==='vote'?`<p class="hint">${r.voteTarget?'✓ Bạn đã bỏ phiếu. Chạm vào người khác để đổi phiếu trước khi hết giờ.':r.self.alive?'🗳️ Chạm vào khung người chơi để bỏ phiếu; bạn có thể đổi trước khi hết giờ.':'Bạn đang theo dõi lượt bỏ phiếu.'}</p>`:''}<div class="gridplayers village-grid">${r.players.map((p,i)=>playerCard(p,r.self.id,state.selection.includes(p.id)||(r.phase==='vote'&&r.voteTarget===p.id),i,r.phase==='vote'&&r.self.alive&&p.alive&&p.id!==r.self.id,roleCardTargetable(r,p),([...((r.voteDetails||[]).filter(v=>v.target===p.id).map(v=>v.number)),...(night&&r.self.role==='wolf'?(r.wolfPickDetails||[]).filter(v=>v.target===p.id).map(v=>v.voterNumber):[])]),(r.lynchChoices||[]).find(v=>v.voter===p.id)?.choice,p.id===r.lynchTarget,[])).join('')}</div></section>${r.self.role==='wolf'?`<div class="wolf-team-strip">🐺 Đồng đội Ma Sói: ${(r.self.wolfTeam||[]).filter(p=>p.id!==r.self.id).map(p=>escapeHTML(p.name)+(p.alive?'':' (đã bị loại)')).join(', ')||'Không có đồng đội'}</div>`:''}<div class="village-role-strip">🎭 ${ROLE[r.self.role]?.[0]||"👤"} <strong>${ROLE[r.self.role]?.[1]||"Vai trò"}</strong> · ${r.players.filter(p=>p.alive).length} người còn sống</div>${r.self.role==='seer'&&r.privateInfo?.startsWith('🔮')?`<section class="seer-result-notice" role="status"><strong>🔮 Thông báo riêng cho Tiên tri</strong><span>${escapeHTML(r.privateInfo)}</span></section>`:''}<nav class="game-tabs" aria-label="Mục chơi">${[['actions','⚡ Hành động'],['chat','💬 Chat'],['role','🎭 Vai trò']].map(([id,label])=>`<button type="button" class="${state.gameTab===id?'active':''}" data-game-tab="${id}">${label}</button>`).join('')}</nav><div class="game-tab-body">${state.gameTab==='actions'?`${lynchPanel(r)}${['night','hunter'].includes(r.phase)?actions(r):r.phase==='discussion'?chat(r):''}`:state.gameTab==='chat'?chat(r):`${roleCard(r)}${r.self.hypnotized?'<section class="panel"><p>🌀 Bạn đã bị thôi miên.</p></section>':''}${r.privateInfo?`<section class="panel"><h3>🔐 Thông tin bí mật</h3><p>${escapeHTML(r.privateInfo)}</p></section>`:''}`}</div>${loveLetters(r)}${willDialog(r)}<button type="button" class="game-exit-button" data-action="leave">🚪 Thoát phòng</button></div>`}
function end(r){const winner=r.messages.findLast?.(m=>m.type==='system'&&m.message.includes('chiến thắng'))?.message||'Ván chơi kết thúc';const text=winner.toLowerCase();const outcome=text.includes('phe làng')?{type:'village',icon:'🏡',label:'PHE LÀNG',title:'CHIẾN THẮNG'}:text.includes('phe sói')?{type:'wolf',icon:'🐺',label:'PHE SÓI',title:'CHIẾN THẮNG'}:text.includes('thằng ngố')?{type:'fool',icon:'🤡',label:'THẰNG NGỐ',title:'CHIẾN THẮNG'}:text.includes('thôi miên')?{type:'hypnotist',icon:'🌀',label:'THÔI MIÊN',title:'CHIẾN THẮNG'}:{type:'unknown',icon:'🏆',label:'VÁN ĐẤU',title:'ĐÃ KẾT THÚC'};return `${header('Kết quả ván')}<section class="panel result result-card result-${outcome.type}" role="status" aria-live="polite"><div class="result-kicker"><span class="result-kicker-dot"></span>KẾT QUẢ VÁN ĐẤU</div><div class="result-emblem"><span class="result-emblem-ring"></span><span class="symbol">${outcome.icon}</span></div><div class="result-content"><span class="result-team">${outcome.label}</span><h2>${outcome.title}</h2><p class="result-description">Bí mật của ngôi làng đã được hé lộ.</p></div><div class="result-ornament" aria-hidden="true"><span></span><b>✦</b><span></span></div></section><section class="panel"><h3>Vai trò của mọi người</h3>${(r.reveal||[]).map(p=>`<div class="listrow"><span class="avatar">${ROLE[p.role]?.[0]||'👤'}</span><div class="grow"><strong>${escapeHTML(p.name)}</strong><small class="muted">${ROLE[p.role]?.[1]||'Không rõ'}${p.isBot?' · 🤖 Máy':''}</small></div></div>`).join('')}</section>${r.host===r.self.id?'<button class="btn gold full" data-action="restart">↻ Chơi lại cùng phòng</button>':'<p class="hint">Chờ chủ phòng bắt đầu ván mới.</p>'}<button class="btn ghost full" style="margin-top:10px" data-action="leave">Rời phòng</button>${loveLetters(r)}`}
function demo(){const phases=['Trang chủ','Danh sách phòng','Tạo phòng','Phòng chờ','Nhận vai trò','Ban đêm','Thảo luận','Bỏ phiếu','Kết quả','Chiến thắng'];let i=state.demoPhase;return `${header('Xem thử giao diện',true)}<section class="phase"><span class="badge">Màn hình ${i+1}/10</span><h2>${phases[i]}</h2><p class="muted">Chế độ tham quan – không kết nối ván thật</p></section>${i===0?'<div class="hero"><div class="moon">🌕</div><h2>MA SÓI</h2><p>NGÔI LÀNG BÍ ẨN</p></div>':i===4?'<div class="cardrole"><div class="symbol">🔮</div><h2>TIÊN TRI</h2><p>Mỗi đêm bạn có thể kiểm tra một người.</p></div>':i===9?'<div class="cardrole"><div class="symbol">🏆</div><h2>PHE LÀNG CHIẾN THẮNG</h2><p>Bình minh đã trở lại ngôi làng.</p></div>':`<section class="panel"><h3>${phases[i]}</h3><div class="gridplayers">${['An','Bình','Chi','Dũng','Hà','Khoa','Linh','Minh','Ngọc'].map((name,j)=>playerCard({id:String(j),name,alive:!(i>=8&&j===3),online:true},'4',false)).join('')}</div></section>${i===5||i===7?'<section class="panel"><h3>Chọn một người</h3><div class="choices"><button class="choice">👤 An <span style="margin-left:auto">○</span></button><button class="choice">👤 Bình <span style="margin-left:auto">○</span></button></div></section>':''}`}<div class="cols"><button class="btn ghost" data-action="demo-prev" ${i===0?'disabled':''}>← Trước</button><button class="btn gold" data-action="demo-next" ${i===9?'disabled':''}>Tiếp →</button></div><p class="scrollnote">Đây là bản xem thử. Để chơi thật, hãy tạo phòng và mời bạn bè.</p>${dock()}`}
state.gameTab='actions';

function unoRpc(event,data={}){return new Promise(resolve=>{unoSocket.timeout(8000).emit(event,data,(err,result)=>resolve(err?{ok:false,error:'Máy chủ UNO không phản hồi. Hãy kiểm tra kết nối.'}:result||{ok:false,error:'Lỗi UNO không xác định.'}))})}
function unoSaveSession(code,playerId){localStorage.setItem('uno_session',JSON.stringify({code,playerId}))}
function unoClearSession(){localStorage.removeItem('uno_session');unoState.room=null;unoState.pendingWild=null;unoState.joinCode='';state.screen='unoHub';render()}
function unoColorName(color){return ({red:'Đỏ',yellow:'Vàng',green:'Xanh lá',blue:'Xanh dương'})[color]||'Chưa chọn'}
function unoCardLabel(card){if(card.type==='number')return card.value;if(card.type==='skip')return '⊘';if(card.type==='reverse')return '↻';if(card.type==='draw2')return '+2';if(card.type==='wild')return '✦';return '+4'}
function unoCardMarkup(card,interactive=false){const color=card.color||'wild';const label=unoCardLabel(card);const extra=interactive?' data-uno-play="'+escapeHTML(card.id)+'"':' aria-hidden="true"';return '<button type="button" class="uno-card uno-card-'+color+(interactive?' uno-card-interactive':' uno-card-static')+'"'+extra+(interactive?' aria-label="Đánh lá '+escapeHTML(label)+' màu '+escapeHTML(unoColorName(card.color))+'"':' tabindex="-1"')+'><span class="uno-card-corner">'+escapeHTML(label)+'</span><span class="uno-card-oval"><span>'+escapeHTML(label)+'</span></span><span class="uno-card-corner uno-card-corner-bottom">'+escapeHTML(label)+'</span></button>'}
function unoHeader(title,back=false){return '<header class="uno-top"><div class="uno-top-left">'+(back?'<button type="button" class="uno-back" data-go="home" aria-label="Trở về trang chủ">←</button>':'')+'<div><h1>'+title+'</h1><small>GAME HUB · MA SÓI HUYỀN BÍ</small></div></div><span class="uno-online">'+(unoSocket.connected?'● Trực tuyến':'○ Đang kết nối')+'</span></header>'}
function unoHub(){return '<div class="uno-page">'+unoHeader('UNO PARTY',true)+'<section class="uno-hub-hero"><div class="uno-hub-orbit"></div><span class="uno-hub-eyebrow">CARD GAME · MULTIPLAYER</span><h2>MỘT VÁN UNO,<br><span>VẠN NIỀM VUI</span></h2><p>Tạo bàn chơi riêng và mời bạn bè tham gia. Ai sẽ là người hết bài đầu tiên?</p><div class="uno-hub-sample">'+['red','yellow','green','blue'].map((color,i)=>'<span class="uno-sample-card uno-'+color+'">'+['7','↻','+2','W'][i]+'</span>').join('')+'</div></section><section class="uno-panel"><div class="uno-section-title"><div><span class="uno-eyebrow">BẮT ĐẦU CUỘC CHƠI</span><h3>Tạo phòng UNO</h3></div><span class="uno-section-icon">✦</span></div><div class="uno-field"><label for="unoRoomName">Tên phòng</label><input id="unoRoomName" maxlength="28" value="UNO Party" placeholder="Tên phòng của bạn"></div><label class="uno-private-toggle"><input id="unoPrivate" type="checkbox"><span>Phòng riêng – chỉ tham gia bằng mã</span></label><button type="button" class="uno-primary-button" data-uno-action="create">＋ TẠO PHÒNG UNO</button></section><section class="uno-panel"><div class="uno-section-title"><div><span class="uno-eyebrow">BẠN ĐÃ CÓ MÃ PHÒNG?</span><h3>Tham gia bạn bè</h3></div><span class="uno-section-icon">⌁</span></div><div class="uno-join-row"><input id="unoRoomCode" maxlength="6" autocapitalize="characters" placeholder="NHẬP MÃ 6 KÝ TỰ" value="'+escapeHTML(unoState.joinCode)+'"><button type="button" class="uno-secondary-button" data-uno-action="join">THAM GIA</button></div></section><section class="uno-panel uno-public-rooms"><div class="uno-section-title"><div><span class="uno-eyebrow">SẴN SÀNG KẾT NỐI</span><h3>Phòng công khai</h3></div><button type="button" class="uno-refresh" data-uno-action="refresh" aria-label="Làm mới danh sách">↻</button></div><div id="unoRoomList"><div class="uno-empty">Đang tải danh sách phòng...</div></div></section><p class="uno-back-note">UNO Party hoạt động độc lập với Ma Sói. Tiến trình và bài trên tay được quản lý riêng.</p></div>'}
function unoLobby(room){const me=room.players.find(player=>player.id===room.self.id);const allReady=room.players.length>=2&&room.players.every(player=>player.ready);return '<div class="uno-page uno-room-page">'+unoHeader('PHÒNG CHỜ UNO')+'<section class="uno-room-banner"><div><span class="uno-eyebrow">MÃ PHÒNG CỦA BẠN</span><strong class="uno-room-code">'+escapeHTML(room.code)+'</strong><small>'+escapeHTML(room.name)+'</small></div><button type="button" class="uno-copy-code" data-uno-action="copy">▣ SAO CHÉP</button></section><section class="uno-panel"><div class="uno-section-title"><div><span class="uno-eyebrow">DANH SÁCH THAM GIA</span><h3>Người chơi <span class="uno-count">'+room.players.length+'/10</span></h3></div><span class="uno-section-icon">♟</span></div><div class="uno-lobby-players">'+room.players.map((player,index)=>'<div class="uno-lobby-player '+(player.id===room.self.id?'is-self':'')+'"><span class="uno-seat">'+String(index+1).padStart(2,'0')+'</span><span class="uno-player-avatar">'+['♠','◆','●','★','✦'][index%5]+'</span><strong>'+escapeHTML(player.name)+'</strong>'+(player.isHost?'<span class="uno-host-tag">CHỦ PHÒNG</span>':'')+'<small class="'+(player.ready?'ready':'waiting')+'">'+(player.ready?'● Sẵn sàng':'◌ Đang chờ')+'</small></div>').join('')+Array.from({length:Math.max(0,4-room.players.length)},(_,i)=>'<div class="uno-lobby-empty"><span>＋</span><small>Chờ người chơi</small></div>').join('')+'</div><p class="uno-muted">Cần ít nhất 2 người. Chủ phòng bắt đầu khi tất cả người chơi đã sẵn sàng.</p></section><div class="uno-lobby-actions">'+(room.self.isHost?'<button type="button" class="uno-primary-button" data-uno-action="start" '+(!allReady?'disabled':'')+'>▶ BẮT ĐẦU VÁN</button>':'<button type="button" class="uno-primary-button" data-uno-action="ready">'+(me?.ready?'✓ ĐÃ SẴN SÀNG':'TÔI ĐÃ SẴN SÀNG')+'</button>')+'<button type="button" class="uno-secondary-button" data-uno-action="leave">RỜI PHÒNG</button></div><section class="uno-chat-panel"><div class="uno-section-title"><div><span class="uno-eyebrow">TRÒ CHUYỆN</span><h3>Phòng chat</h3></div></div><div class="uno-chat-log">'+room.messages.slice(-8).map(message=>'<p><strong>'+escapeHTML(message.name||'Hệ thống')+'</strong> '+escapeHTML(message.message)+'</p>').join('')+'</div><form id="unoChatForm" class="uno-chat-form"><input id="unoChatInput" maxlength="240" placeholder="Nhắn tin cho mọi người..."><button type="submit" aria-label="Gửi tin nhắn">➤</button></form></section></div>'}
function unoGame(room){const selfTurn=room.currentPlayerId===room.self.id;const canDraw=selfTurn&&!room.challenge&&!room.turnDrawnCardId;const canPass=selfTurn&&!room.challenge&&!!room.turnDrawnCardId;const opponents=room.players.filter(player=>player.id!==room.self.id);const top=room.topCard;const pending=room.pendingUno;let challengeBox='';if(room.challenge){challengeBox=room.challenge.canRespond?'<section class="uno-challenge-box"><strong>⚖️ THÁCH THỨC +4</strong><p>'+escapeHTML(room.challenge.offenderName)+' vừa đánh lá +4. Bạn có thể chấp nhận hoặc thách thức.</p><div><button type="button" data-uno-action="challenge">THÁCH THỨC</button><button type="button" data-uno-action="accept">CHẤP NHẬN +4</button></div></section>':'<div class="uno-notice">⚖️ '+escapeHTML(room.challenge.challengerName)+' đang xử lý lá +4 của '+escapeHTML(room.challenge.offenderName)+'.</div>'}let unoNotice='';if(pending){unoNotice=pending.playerId===room.self.id?'<button type="button" class="uno-call-button" data-uno-action="call">UNO! GỌI UNO NGAY</button>':'<div class="uno-catch-row"><span>⚠️ '+escapeHTML(pending.playerName)+' còn 1 lá!</span><button type="button" data-uno-action="catch">BẮT LỖI UNO</button></div>'}const wildModal=unoState.pendingWild?'<div class="uno-color-overlay"><section class="uno-color-dialog"><button type="button" class="uno-modal-close" data-uno-action="cancel-wild">×</button><span class="uno-eyebrow">WILD CARD</span><h3>CHỌN MÀU TIẾP THEO</h3><div class="uno-color-options">'+UNO_CLIENT_COLORS.map(color=>'<button type="button" class="uno-color-pick uno-'+color+'" data-uno-color="'+color+'" aria-label="'+unoColorName(color)+'"></button>').join('')+'</div></section></div>':'';return '<div class="uno-page uno-game-page">'+unoHeader('UNO PARTY')+'<div class="uno-game-meta"><span>PHÒNG '+escapeHTML(room.code)+'</span><span>'+room.players.length+' NGƯỜI CHƠI</span><span>CHIỀU '+(room.direction===1?'↻':'↺')+'</span></div><section class="uno-opponents">'+opponents.map(player=>'<div class="uno-opponent '+(player.id===room.currentPlayerId?'is-turn':'')+'"><span class="uno-opponent-avatar">'+(player.online?'♟':'◌')+'</span><strong>'+escapeHTML(player.name)+'</strong><span class="uno-opponent-count">'+player.cardCount+' lá</span>'+(player.id===room.currentPlayerId?'<small>ĐANG LƯỢT</small>':'')+'</div>').join('')+'</section><section class="uno-table"><div class="uno-table-glow"></div><div class="uno-turn-status '+(selfTurn?'your-turn':'')+'">'+(selfTurn?'ĐẾN LƯỢT BẠN':('ĐANG LƯỢT: '+escapeHTML(room.currentPlayerName)))+'</div><div class="uno-piles"><button type="button" class="uno-draw-pile" data-uno-action="draw" '+(!canDraw?'disabled':'')+'><span>UNO</span><small>RÚT BÀI</small><b>'+room.drawPileCount+'</b></button><div class="uno-discard-pile">'+(top?unoCardMarkup(top,false):'')+'</div></div><div class="uno-current-color">MÀU HIỆN TẠI <strong class="uno-color-dot uno-'+room.currentColor+'"></strong><b>'+unoColorName(room.currentColor)+'</b></div><div class="uno-turn-hint">'+(selfTurn?(room.turnDrawnCardId?'Bạn có thể đánh lá vừa rút hoặc kết thúc lượt.':'Đánh một lá hợp lệ hoặc rút một lá bài.'):'Hãy quan sát lượt chơi của mọi người.')+'</div></section>'+challengeBox+unoNotice+(canPass?'<button type="button" class="uno-pass-button" data-uno-action="pass">BỎ QUA LƯỢT</button>':'')+'<section class="uno-hand-section"><div class="uno-hand-heading"><div><span class="uno-eyebrow">BÀI TRÊN TAY</span><h3>'+escapeHTML(room.self.name)+' <span>'+room.hand.length+' LÁ</span></h3></div><span class="uno-hand-tip">'+(selfTurn?'Chạm vào lá bài để đánh':'Đang chờ lượt')+'</span></div><div class="uno-hand">'+room.hand.map(card=>unoCardMarkup(card,selfTurn&&!room.challenge)).join('')+'</div></section><section class="uno-chat-panel uno-game-chat"><details><summary>💬 Trò chuyện trong phòng</summary><div class="uno-chat-log">'+room.messages.slice(-8).map(message=>'<p><strong>'+escapeHTML(message.name||'Hệ thống')+'</strong> '+escapeHTML(message.message)+'</p>').join('')+'</div><form id="unoChatForm" class="uno-chat-form"><input id="unoChatInput" maxlength="240" placeholder="Nhắn tin..."><button type="submit" aria-label="Gửi tin nhắn">➤</button></form></details></section><button type="button" class="uno-exit-link" data-uno-action="leave">Rời ván UNO</button>'+wildModal+'</div>'}
function unoEnd(room){const winner=room.players.find(player=>player.id===room.winnerId);return '<div class="uno-page uno-end-page">'+unoHeader('KẾT QUẢ UNO')+'<section class="uno-result-card"><span class="uno-eyebrow">UNO PARTY · KẾT THÚC VÁN</span><div class="uno-result-trophy">🏆</div><span class="uno-result-winner">NGƯỜI CHIẾN THẮNG</span><h2>'+escapeHTML(winner?.name||'Người chơi')+'</h2><p>Đã đánh hết bài và giành chiến thắng!</p><div class="uno-result-confetti" aria-hidden="true">✦　✧　✦</div></section><section class="uno-panel"><div class="uno-section-title"><div><span class="uno-eyebrow">BẢNG XẾP HẠNG</span><h3>Kết quả người chơi</h3></div></div><div class="uno-results-list">'+room.results.map((player,index)=>'<div class="uno-result-row"><span class="uno-result-rank">'+(index===0?'🏆':String(index+1).padStart(2,'0'))+'</span><strong>'+escapeHTML(player.name)+'</strong><span>'+player.cardsLeft+' lá còn lại</span></div>').join('')+'</div></section>'+(room.self.isHost?'<button type="button" class="uno-primary-button" data-uno-action="restart">↻ CHƠI VÁN MỚI</button>':'<p class="uno-muted">Chờ chủ phòng tạo ván mới.</p>')+'<button type="button" class="uno-secondary-button" data-uno-action="leave">VỀ GAME HUB</button></div>'}
const UNO_CLIENT_COLORS=['red','yellow','green','blue'];
function loadUnoRooms(){if(state.screen!=='unoHub'||unoState.room)return;unoState.loading=true;unoRpc('uno:room:list').then(result=>{unoState.loading=false;if(!result.ok){const el=document.querySelector('#unoRoomList');if(el)el.innerHTML='<div class="uno-empty">Không thể tải phòng. <button data-uno-action="refresh">Thử lại</button></div>';return}unoState.rooms=result.rooms||[];const el=document.querySelector('#unoRoomList');if(!el)return;el.innerHTML=unoState.rooms.length?unoState.rooms.map(room=>'<div class="uno-room-list-row"><div class="uno-room-list-icon">UNO</div><div class="uno-room-list-info"><strong>'+escapeHTML(room.name)+'</strong><small>'+escapeHTML(room.code)+' · '+room.count+'/'+room.max+' người</small></div><button type="button" class="uno-join-room-button" data-uno-join="'+escapeHTML(room.code)+'">VÀO</button></div>').join(''):'<div class="uno-empty">Chưa có phòng UNO công khai. Hãy tạo phòng đầu tiên!</div>'})}
async function unoAction(type){if(unoState.loading)return;unoState.loading=true;let result;try{const room=unoState.room;switch(type){case 'refresh':unoState.loading=false;loadUnoRooms();return;case 'create':{const playerName=getName();if(!playerName){unoState.loading=false;return}result=await unoRpc('uno:room:create',{name:document.querySelector('#unoRoomName')?.value||'UNO Party',playerName,private:!!document.querySelector('#unoPrivate')?.checked});if(result.ok)unoSaveSession(result.code,result.playerId);break}case 'join':{const playerName=getName();if(!playerName){unoState.loading=false;return}const code=(document.querySelector('#unoRoomCode')?.value||unoState.joinCode).trim().toUpperCase();if(code.length!==6){unoState.loading=false;toast('Mã phòng phải có 6 ký tự.');return}result=await unoRpc('uno:room:join',{code,playerName});if(result.ok)unoSaveSession(result.code,result.playerId);break}case 'ready':{const own=room.players.find(player=>player.id===room.self.id);result=await unoRpc('uno:room:ready',!own?.ready);break}case 'start':result=await unoRpc('uno:room:start');break;case 'copy':await navigator.clipboard?.writeText(room.code).catch(()=>{});toast('Đã sao chép mã phòng '+room.code);unoState.loading=false;return;case 'leave':if(room?.phase==='playing'&&!window.confirm('Rời ván UNO? Bạn sẽ bị loại khỏi bàn chơi.')){unoState.loading=false;return}result=await unoRpc('uno:room:leave');if(result.ok){unoClearSession();unoState.loading=false;loadUnoRooms();return}break;case 'draw':result=await unoRpc('uno:game:draw');break;case 'pass':result=await unoRpc('uno:game:pass');break;case 'call':result=await unoRpc('uno:game:call');break;case 'catch':result=await unoRpc('uno:game:catch');break;case 'challenge':result=await unoRpc('uno:game:challenge');break;case 'accept':result=await unoRpc('uno:game:accept');break;case 'restart':result=await unoRpc('uno:game:restart');break;case 'cancel-wild':unoState.pendingWild=null;render();unoState.loading=false;return;default:unoState.loading=false;return}if(result&&!result.ok)toast(result.error)}finally{unoState.loading=false}}
async function unoPlayCard(cardId,color){const result=await unoRpc('uno:game:play',{cardId,color});if(!result.ok){toast(result.error);return}unoState.pendingWild=null}
function unoRenderRoom(){const room=unoState.room;if(!room)return '';if(room.phase==='lobby')return unoLobby(room);if(room.phase==='ended')return unoEnd(room);return unoGame(room)}

function render(){const r=state.room;const inUno=!r&&(!!unoState.room||state.screen==='unoHub');let html=r?(r.phase==='lobby'?lobby(r):r.phase==='reveal'?revealScreen(r):r.phase==='ended'?end(r):game(r)):inUno?(unoState.room?unoRenderRoom():unoHub()):({home,create,join,rooms,guide,demo,ai}[state.screen]?.()||home());const appClass=r?'app-room':inUno?'app-uno':'app-'+state.screen;app.innerHTML=`<main class="app ${appClass}">${html}</main>${eliminationDialog()}${r&&r.phase!=='lobby'?soundPanel():''}`;updateClock();document.body.classList.toggle('in-game',!!r&&r.phase!=='lobby'&&r.phase!=='ended');document.body.classList.toggle('in-uno',!!unoState.room&&unoState.room.phase==='playing');if(state.screen==='rooms'&&!r)loadRooms();if(state.screen==='unoHub'&&!r&&!unoState.room)loadUnoRooms();let chatlog=document.querySelector('#chatlog');if(chatlog)chatlog.scrollTop=chatlog.scrollHeight;let loveLog=document.querySelector('#loveLog');if(loveLog)loveLog.scrollTop=loveLog.scrollHeight;let unoChat=document.querySelector('.uno-chat-log');if(unoChat)unoChat.scrollTop=unoChat.scrollHeight}
function updateClock(){let clock=document.querySelector('#clock');if(!clock||!state.room?.deadline)return;let s=Math.max(0,Math.ceil((state.room.deadline-Date.now())/1000));clock.textContent=`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
setInterval(updateClock,500);
setInterval(()=>{if(!state.room&&state.screen==='rooms'&&socket.connected)loadRooms()},5000);
async function loadRooms(){if(state.room||state.screen!=='rooms')return;let res=await rpc('room:list',{});let el=document.querySelector('#roomlist');if(!el||state.room||state.screen!=='rooms')return;if(!res.ok){el.innerHTML=`<div class="empty">⚠️ ${escapeHTML(res.error)}<br><button class="btn small ghost" data-action="refresh">↻ Thử lại</button></div>`;return}const pageSize=4,pages=Math.max(1,Math.ceil(res.rooms.length/pageSize));state.roomsPage=Math.min(state.roomsPage,pages-1);el.innerHTML=res.rooms.length?res.rooms.slice(state.roomsPage*pageSize,(state.roomsPage+1)*pageSize).map(r=>`<div class="listrow"><div class="avatar">🏘️</div><div class="grow"><strong>${escapeHTML(r.name)}</strong><small class="muted">${r.count}/${r.max} người · Đang chờ</small></div><button class="btn small" data-joincode="${r.code}">Vào</button></div>`).join('')+`<div class="page-controls"><button class="btn small ghost" data-room-page="-1" ${state.roomsPage===0?'disabled':''}>←</button><span>${state.roomsPage+1}/${pages}</span><button class="btn small ghost" data-room-page="1" ${state.roomsPage>=pages-1?'disabled':''}>→</button></div>` :'<div class="empty">Hiện chưa có phòng công khai đang chờ. Bạn có thể tạo phòng công khai mới, hoặc nhập mã để vào phòng riêng.</div>'}
function getName(){let name=document.querySelector('#playerName')?.value.trim()||state.name||'';if(!name){toast('Vui lòng nhập biệt danh.');return null}state.name=name.slice(0,18);localStorage.setItem('wolf_name',state.name);return state.name}
async function joinRoom(code){let name=getName();if(!name)return;let res=await rpc('room:join',{code,playerName:name});if(!res.ok)return toast(res.error);saveSession(res.code,res.playerId)}
async function syncNightDraft(){const a=state.room?.action;if(!a||a.kind==='wait'||a.kind==='vote'||a.kind==='lynch'||state.room?.phase!=='night')return;const data={targets:[...state.selection]};if(a.kind==='witch')data.choice=state.witchChoice;const res=await rpc('room:role-draft',data);if(!res.ok)toast(res.error)}
async function saveNightChoice(){const a=state.room?.action;if(!a||a.kind==='wait'||a.kind==='vote'||a.submitted)return;const selected=state.selection.length?state.selection:Array.isArray(a.draft?.targets)?a.draft.targets:[a.draft?.target].filter(Boolean);let data={};if(a.kind==='witch'){data.choice=a.draft?.choice||state.witchChoice;if(data.choice==='poison'){if(!selected[0])return;data.target=selected[0]}}else if(a.kind==='cupid'||a.kind==='hypnotist'){const count=a.kind==='cupid'||state.room.players.length>=11?2:1;if(selected.length!==count)return;data.targets=[...selected]}else{if(!selected[0])return;data.target=selected[0]}const res=await rpc('room:action',data);if(!res.ok)toast(res.error)}
async function action(type){if(pending)return;pending=true;try{let r=state.room,res;switch(type){case 'refresh':return loadRooms();case 'create-ai':{let playerName=getName();if(!playerName)return;res=await rpc('room:create-bots',{playerName,discussion:45});if(res.ok)saveSession(res.code,res.playerId);break}case 'create':{let playerName=getName();if(!playerName)return;res=await rpc('room:create',{name:document.querySelector('#roomName').value,playerName,private:document.querySelector('#private').checked,discussion:Number(document.querySelector('#discussion').value)});if(res.ok)saveSession(res.code,res.playerId);break}case 'join':return joinRoom(document.querySelector('#roomCode').value.trim().toUpperCase());case 'copy':await navigator.clipboard?.writeText(`${location.origin}/?room=${r.code}`).catch(()=>{});toast(`Mã phòng: ${r.code}`);return;case 'ready':res=await rpc('room:ready',!r.players.find(p=>p.id===r.self.id)?.ready);break;case 'add-bot':res=await rpc('room:add-bot',{});if(res.ok)toast('🤖 Đã thêm một người chơi máy.');break;case 'start':res=await rpc('room:start',{});break;case 'leave':{if(r&&r.phase!=='lobby'&&r.phase!=='ended'){if(!window.confirm('Thoát trận ngay? Bạn sẽ bị loại khỏi ván và không thể tham gia lại bằng phiên này.'))return;}res=await rpc('room:leave',{});if(res.ok){clearSession();state.room=null;state.selection=[];render();}break;}case 'restart':res=await rpc('room:restart',{});break;case 'demo-prev':state.demoPhase=Math.max(0,state.demoPhase-1);render();return;case 'demo-next':state.demoPhase=Math.min(9,state.demoPhase+1);render();return;case 'submit':{let a=r?.action;if(!a)return;let data={};if(a.kind==='witch'){data.choice=state.witchChoice;if(data.choice==='poison')data.target=state.selection[0];if(data.choice==='poison'&&!data.target)return toast('Chọn người muốn dùng độc.')}else if(a.kind==='cupid'){if(state.selection.length!==2)return toast('Chọn đúng hai người.');data.targets=state.selection}else{if(state.selection.length!==1)return toast('Chọn một người.');data.target=state.selection[0]}res=await rpc('room:action',data);if(res.ok)state.selection=[];break}}
 if(res&&!res.ok)toast(res.error)}finally{pending=false}}
app.addEventListener('click',async e=>{const play=e.target.closest('[data-uno-play]');if(play){e.preventDefault();e.stopImmediatePropagation();const card=unoState.room?.hand.find(item=>item.id===play.dataset.unoPlay);if(!card)return;if(card.type==='wild'||card.type==='wild4'){unoState.pendingWild=card.id;render();}else{await unoPlayCard(card.id);}return}const color=e.target.closest('[data-uno-color]');if(color){e.preventDefault();e.stopImmediatePropagation();const id=unoState.pendingWild;if(id)await unoPlayCard(id,color.dataset.unoColor);return}const join=e.target.closest('[data-uno-join]');if(join){e.preventDefault();e.stopImmediatePropagation();const field=document.querySelector('#unoRoomCode');if(field)field.value=join.dataset.unoJoin;await unoAction('join');return}const action=e.target.closest('[data-uno-action]');if(action){e.preventDefault();e.stopImmediatePropagation();await unoAction(action.dataset.unoAction)}});
app.addEventListener('click',async e=>{if(soundPrefs.enabled)audioReady();let soundToggle=e.target.closest('[data-sound-toggle]');if(soundToggle){setSoundEnabled(!soundPrefs.enabled);return}let guidePage=e.target.closest('[data-guide-page]');if(guidePage){state.guideIndex=Math.max(0,Math.min(Object.keys(ROLE).length,state.guideIndex+Number(guidePage.dataset.guidePage)));render();return}let avatarChoice=e.target.closest('[data-avatar]');if(avatarChoice){const res=await rpc('room:avatar',{avatar:avatarChoice.dataset.avatar});if(!res.ok)toast(res.error);return}let lobbyTab=e.target.closest('[data-lobby-tab]');if(lobbyTab){state.lobbyTab=lobbyTab.dataset.lobbyTab;render();return}let roomPage=e.target.closest('[data-room-page]');if(roomPage){state.roomsPage=Math.max(0,state.roomsPage+Number(roomPage.dataset.roomPage));loadRooms();return}let nav=e.target.closest('[data-go]');if(nav){if(state.room)return toast('Hãy rời phòng trước khi chuyển trang.');go(nav.dataset.go);return}let code=e.target.closest('[data-joincode]');if(code){await joinRoom(code.dataset.joincode);return}let willTarget=e.target.closest('[data-will-player]');if(willTarget){e.preventDefault();e.stopPropagation();state.willDialog={playerId:willTarget.dataset.willPlayer};render();return}let closeWill=e.target.closest('[data-close-will]');if(closeWill){e.preventDefault();state.willDialog=null;render();return}let witch=e.target.closest('[data-witch]');if(witch){state.witchChoice=witch.dataset.witch;state.selection=[];await syncNightDraft();render();return}let unselect=e.target.closest('[data-unselect]');if(unselect){state.selection=state.selection.filter(id=>id!==unselect.dataset.unselect);await syncNightDraft();render();return}let confirmRole=e.target.closest('[data-confirm-role]');if(confirmRole){if(confirmRole.disabled)return;await saveNightChoice();return}let lynchButton=e.target.closest('[data-lynch]');if(lynchButton){const r=state.room;if(pending||r?.phase!=='lynch'||!r.self.alive||r.self.id===r.lynchTarget)return;pending=true;try{const res=await rpc('room:action',{choice:lynchButton.dataset.lynch});toast(res.ok?'⚖️ Đã cập nhật quyết định.':res.error)}finally{pending=false}return}let dismiss=e.target.closest('[data-dismiss-elimination]');if(dismiss){state.eliminationNotice=null;render();return}let tab=e.target.closest('[data-game-tab]');if(tab){state.gameTab=tab.dataset.gameTab;render();return}let voteCard=e.target.closest('[data-vote-player]');if(voteCard){const r=state.room,id=voteCard.dataset.votePlayer;if(pending||r?.phase!=='vote'||!r.self.alive||!r.action?.targets?.some(p=>p.id===id))return;pending=true;voteCard.disabled=true;try{const res=await rpc('room:action',{target:id});if(!res.ok){toast(res.error);voteCard.disabled=false}else toast(r.voteTarget?'🗳️ Đã đổi phiếu bầu.':'🗳️ Đã ghi nhận phiếu bầu.')}finally{pending=false}return}let roleCard=e.target.closest('[data-role-player]');if(roleCard){const r=state.room,a=r?.action,id=roleCard.dataset.rolePlayer;if(!a||a.submitted||!roleCardTargetable(r,{id}))return;state.selection=a.kind==='cupid'||a.kind==='hypnotist'&&r.players.length>=11?(state.selection.includes(id)?state.selection.filter(x=>x!==id):[...state.selection.slice(-1),id]):[id];await syncNightDraft();render();return}let selected=e.target.closest('[data-select]');if(selected){let id=selected.dataset.select;let kind=state.room?.action?.kind;if(kind==='cupid'||kind==='hypnotist'&&state.room.players.length>=11){state.selection=state.selection.includes(id)?state.selection.filter(x=>x!==id):[...state.selection.slice(-1),id]}else state.selection=[id];await syncNightDraft();render();return}let loveToggle=e.target.closest('[data-love-toggle]');if(loveToggle){state.loveOpen=!state.loveOpen;if(state.loveOpen)state.loveUnread=0;render();return}let kick=e.target.closest('[data-kick]');if(kick){let target=state.room?.players.find(p=>p.id===kick.dataset.kick);if(!target||!confirm(`Mời ${target.name} ra khỏi phòng?`))return;let res=await rpc('room:kick',{playerId:target.id});toast(res.ok?'Đã mời người chơi ra khỏi phòng.':res.error);return}let btn=e.target.closest('[data-action]');if(btn)await action(btn.dataset.action)});
app.addEventListener('input',e=>{if(e.target.matches('[data-sound-volume]')){soundPrefs.volume=Number(e.target.value);localStorage.setItem('wolf_sound_volume',String(soundPrefs.volume));if(audioReady())soundMaster.gain.setTargetAtTime(soundPrefs.enabled?soundPrefs.volume:0,soundCtx.currentTime,.04)}});
app.addEventListener('keydown',e=>{const book=e.target.closest('[data-will-player]');if(book&&(e.key==='Enter'||e.key===' ')){e.preventDefault();e.stopPropagation();state.willDialog={playerId:book.dataset.willPlayer};render()}});
app.addEventListener('submit',async e=>{if(e.target.id!=='unoChatForm')return;e.preventDefault();const input=document.querySelector('#unoChatInput');const value=input?.value.trim();if(!value)return;const result=await unoRpc('uno:chat:send',value);if(!result.ok)toast(result.error);else if(input)input.value=''});
app.addEventListener('submit',async e=>{if(e.target.id==='playerWillForm'){e.preventDefault();let input=document.querySelector('#playerWillInput');const res=await rpc('room:will',input?.value||'');if(!res.ok)toast(res.error);else{toast('📓 Đã lưu di chúc.');state.willDialog=null;render()}return}if(e.target.id==='loveForm'){e.preventDefault();let input=document.querySelector('#loveInput'),value=input?.value.trim();if(!value)return;let res=await rpc('room:love-letter',value);if(!res.ok)toast(res.error);else if(input)input.value='';return}if(e.target.id!=='chatForm')return;e.preventDefault();let input=document.querySelector('#chatInput'),value=input?.value.trim();if(!value)return;let res=await rpc('room:chat',value);if(!res.ok)toast(res.error);else if(input)input.value='' });
socket.on('room:state',r=>{const priorRoom=state.room;let previous=priorRoom?.phase;if(priorRoom&&r.phase!==previous)soundPhaseChange(previous,r.phase,r);if(priorRoom&&r.phase!=='ended'&&r.players.filter(p=>p.alive).length<priorRoom.players.filter(p=>p.alive).length&&r.phase!=='night')soundElimination();if(priorRoom?.self?.alive&&!r.self.alive&&r.phase!=='ended'){const recent=r.messages.filter(m=>m.type==='system').slice(-8).reverse();const mine=r.players.find(p=>p.id===r.self.id);const matching=recent.find(m=>m.message.includes(mine?.name||'\u0000')&&(/loại|mất|súng|độc|treo|quyết định/i).test(m.message));state.eliminationNotice=priorRoom.phase==='lynch'||r.phase==='lynch'?'Ngôi làng đã treo cổ bạn sau phiên xét xử.':matching?.message||'Bạn đã rời khỏi ván chơi. Các hành động của bạn không còn hiệu lực.';}const previousLetters=state.room?.loveLetters||[];const newLetters=r.loveLetters||[];if(r.self.lover&&!state.loveOpen&&newLetters.length>previousLetters.length){let newIncoming=newLetters.slice(previousLetters.length).filter(m=>m.from!==r.self.id).length;state.loveUnread+=newIncoming;if(newIncoming)toast('💌 Bạn nhận được thư Cupid mới!')}if(!r.self.lover){state.loveOpen=false;state.loveUnread=0}state.room=r;if(previous!==r.phase||priorRoom?.action?.kind!==r.action?.kind){state.gameTab='actions';state.selection=[];state.witchChoice='skip'}render()});
socket.on('room:list-updated',()=>{if(!state.room&&state.screen==='rooms')loadRooms()});
socket.on('connect',async()=>{const saved=JSON.parse(localStorage.getItem('wolf_session')||'null');if(saved){let res=await rpc('room:resume',saved);if(!res.ok){clearSession();toast(res.error)}}else render()});
socket.on('room:kicked',data=>{clearSession();toast(data?.message||'Bạn đã được mời ra khỏi phòng.');});socket.on('room:expired',data=>{clearSession();toast(data?.message||'Phòng chờ đã hết hạn và được tự động xóa.');});
socket.on('disconnect',()=>{toast('Mất kết nối. Đang thử kết nối lại...');render()});
unoSocket.on('connect',async()=>{const saved=JSON.parse(localStorage.getItem('uno_session')||'null');if(saved){const result=await unoRpc('uno:room:resume',saved);if(!result.ok){localStorage.removeItem('uno_session');unoState.room=null;if(result.error!=='Không tìm thấy phiên UNO để khôi phục.')toast(result.error);}}if(state.screen==='unoHub')loadUnoRooms()});
unoSocket.on('uno:state',room=>{unoState.room=room;unoState.pendingWild=null;if(!state.room){state.screen='unoHub';render()}});
unoSocket.on('uno:rooms-updated',()=>{if(state.screen==='unoHub'&&!unoState.room)loadUnoRooms()});
unoSocket.on('uno:session:replaced',()=>{localStorage.removeItem('uno_session');unoState.room=null;toast('Phiên UNO đã được mở ở kết nối khác.');render()});
unoSocket.on('disconnect',()=>{if(unoState.room)toast('Mất kết nối UNO. Đang thử kết nối lại...')});
const urlCode=new URLSearchParams(location.search).get('room');if(urlCode){state.joinCode=urlCode.toUpperCase().slice(0,6);state.screen='join'}render();
